export type AnyEntry = {
    readonly declaration: ModuleDeclaration;
    readonly factory: EntryFactory;
};

export type AnyInputEntry<C> = {
    readonly [uses]: {
        readonly [K in keyof C]?: (capability: C[K]) => C[K];
    };
    readonly [detail]: {
        readonly declaration: ModuleDeclaration;
        readonly instance: unknown;
    };
    readonly declaration: ModuleDeclaration;
    readonly [input]: true;
};

export type AnyModuleEntry<C> = {
    readonly [uses]: {
        readonly [K in keyof C]?: (capability: C[K]) => C[K];
    };
    readonly [detail]: {
        readonly declaration: ModuleDeclaration;
        readonly instance: unknown;
    };
    readonly declaration: ModuleDeclaration;
    readonly factory: EntryFactory;
    readonly [input]?: never;
};

export type Assembly<C> = {
    readonly prepare: <const R extends RootEntries<C>, const N extends InputEntries<C> = {}, const M extends readonly ModuleItem<C>[] = readonly ModuleItem<C>[]>(input: AssemblyPrepareInput<C, R, N, M>) => Promise<AssemblyPreparationResult<R, N>>;
};

export type AssemblyOutcome<R> = {
    readonly status: "succeeded";
    readonly roots: RootInstances<R>;
    readonly created: readonly CreatedEntry[];
} | {
    readonly status: "cancelled";
    readonly reason: unknown;
    readonly created: readonly CreatedEntry[];
} | {
    readonly status: "failed";
    readonly phase: "inputs" | "factory" | "completion" | "internal";
    readonly code: RunErrorCode;
    readonly implementationId: string | undefined;
    readonly cause: unknown;
    readonly created: readonly CreatedEntry[];
    readonly returned: ReturnedProduct | undefined;
    readonly cancellation: ObservedCancellation | undefined;
};

export type AssemblyPreparationResult<R, N = {}> = {
    readonly status: "prepared";
    readonly prepared: PreparedAssembly<R, N>;
    readonly composition: SuccessfulComposition;
} | {
    readonly status: "failed";
    readonly error: {
        readonly code: PreparationErrorCode;
        readonly cause: unknown;
    };
    readonly diagnostics: readonly Diagnostic[];
};

export type AssemblyPrepareInput<C, R extends RootEntries<C>, N extends InputEntries<C> = {}, M extends readonly ModuleItem<C>[] = readonly ModuleItem<C>[]> = {
    readonly modules: M & KnownCapabilities<C, M, N>;
    readonly roots: R;
    readonly inputs?: N | undefined;
} & ({
    readonly composition: SuccessfulComposition;
    readonly profileId?: never;
    readonly bindings?: never;
} | {
    readonly profileId: string;
    readonly bindings?: CompositionProfile["bindings"];
    readonly composition?: never;
    readonly modules: TupleOnly<M>;
});

export type CapabilitiesOf<T extends AnyContract> = {
    readonly [X in T as X["id"]]: X extends {
        readonly id: infer Id extends string;
        readonly revision: infer Rev extends number;
        readonly [contractValue]?: infer V;
    } ? CapabilityContract<V, `${Id}/r${Rev}`> : never;
};

export type CapabilitiesProvidedBy<E> = E extends {
    readonly [detail]: {
        readonly declaration: infer D extends ModuleDeclaration;
        readonly used: infer U;
    };
} ? FactoryCapabilities<U, D> : never;

export type CapabilityBrand<C, K extends keyof C> = {
    readonly [P in K]: (capability: C[P]) => C[P];
};

export type CapabilityContract<Value, Token extends string> = {
    readonly value: Value;
    readonly compatibility: {
        readonly family: "exact";
        readonly familyVersion: 1;
        readonly token: Token;
    };
};

export type CapabilitySchema<C> = {
    readonly [K in keyof C]: CapabilityContract<unknown, string>;
};

export type Contract<Id extends string, V, Rev extends number> = {
    readonly id: Id;
    readonly revision: Rev;
    readonly provide: () => ProvidedEntry<Id, Rev>;
    readonly slot: <const S extends string, const K extends Cardinality>(slotId: S, cardinality: K) => SlotEntry<Id, Rev, S, K>;
    readonly [contractValue]?: V;
};

export type CreatedEntry = {
    readonly moduleId: string;
    readonly implementationId: string;
    readonly instance: unknown;
    readonly capabilities: Readonly<Record<string, unknown>>;
};

export type DeclarationSpec = {
    readonly moduleId: string;
    readonly implementationId: string;
    readonly owner: ModuleDeclaration["owner"];
    readonly provides: readonly ProvidedEntry<string, number>[];
    readonly slots: readonly SlotEntry<string, number, string, Cardinality>[];
};

export type Declared<T extends DeclarationSpec> = T & {
    readonly kind: "get-modular.module-declaration";
    readonly schemaVersion: 1;
};

export type DependenciesOf<E> = E extends {
    readonly [detail]: {
        readonly declaration: infer D extends ModuleDeclaration;
        readonly used: infer U;
    };
} ? FactoryDependencies<U, D> : never;

export type DuplicateModule = {
    readonly implementationId: string;
    readonly paths: readonly (readonly string[])[];
    readonly inputs: readonly string[];
};

export type FactoryCapabilities<C, D extends ModuleDeclaration> = {
    readonly [P in D["provides"][number] as P["capabilityId"]]: P["capabilityId"] extends keyof C ? C[P["capabilityId"]] extends {
        readonly value: infer V;
    } ? V : never : never;
};

export type FactoryContext = {
    readonly signal: AbortSignal;
    readonly scope: unknown;
};

export type FactoryDependencies<C, D extends ModuleDeclaration> = {
    readonly [S in D["slots"][number] as S["slotId"]]: S["cardinality"]["kind"] extends "many" ? readonly (S["capabilityId"] extends keyof C ? C[S["capabilityId"]] extends {
        readonly value: infer V;
    } ? V : never : never)[] : S["cardinality"]["kind"] extends "optional" ? (S["capabilityId"] extends keyof C ? C[S["capabilityId"]] extends {
        readonly value: infer V;
    } ? V : never : never) | undefined : S["capabilityId"] extends keyof C ? C[S["capabilityId"]] extends {
        readonly value: infer V;
    } ? V : never : never;
};

export type FactoryProduct<I, P> = {
    readonly instance: I;
    readonly capabilities: P;
};

export type InputEntry<C, D extends ModuleDeclaration = ModuleDeclaration> = {
    readonly [uses]: CapabilityBrand<C, UsedCapability<D> & keyof C>;
    readonly [detail]: {
        readonly declaration: D;
        readonly instance: FactoryCapabilities<C, D>;
    };
    readonly declaration: D;
    readonly [input]: true;
};

export type InstanceOf<E> = E extends {
    readonly [detail]: {
        readonly instance: infer I;
    };
} ? I : never;

export type IsUnion<T, Whole = T> = T extends Whole ? [
    Whole
] extends [
    T
] ? false : true : never;

export type KnownCapabilities<C, M extends readonly unknown[], N> = [
    Exclude<UsedKeysOf<M[number]> | (N[keyof N] extends infer H ? H extends {
        readonly [uses]: infer U;
    } ? keyof U : never : never), keyof C>
] extends [
    infer Missing
] ? [
    Missing
] extends [
    never
] ? unknown : {
    readonly "capabilities missing from the preparing map": Missing;
} : never;

export type ModuleEntry<C, D extends ModuleDeclaration = ModuleDeclaration, I = unknown> = {
    readonly [uses]: CapabilityBrand<C, UsedCapability<D> & keyof C>;
    readonly [detail]: {
        readonly declaration: D;
        readonly instance: I;
        readonly used: UsedMap<C, UsedCapability<D> & keyof C>;
    };
    readonly declaration: D;
    readonly factory: EntryFactory;
};

export type ModuleGroup<E = AnyEntry, K = unknown> = {
    readonly name: string;
    readonly members: readonly (AnyEntry | ModuleGroup)[];
    readonly [groupEntries]?: E;
    readonly [groupUses]?: K;
};

export type ObservedCancellation = {
    readonly reason: unknown;
};

export type PreparedAssembly<R, N = {}> = {
    readonly run: (...options: {} extends N ? [
        options?: RunOptions<N>
    ] : [
        options: RunOptions<N> & {
            readonly inputs: RunInputs<N>;
        }
    ]) => Promise<AssemblyOutcome<R>>;
};

export type ProvidedEntry<Id extends string, Rev extends number> = {
    readonly capabilityId: Id;
    readonly compatibility: {
        readonly family: "exact";
        readonly familyVersion: 1;
        readonly token: `${Id}/r${Rev}`;
    };
    readonly [contractEntry]: true;
};

export type ReturnedProduct = {
    readonly implementationId: string;
    readonly product: unknown;
};

export type RootInstances<R> = {
    readonly [K in keyof R]: R[K] extends {
        readonly [detail]: {
            readonly instance: infer I;
        };
    } ? I : never;
};

export type RunInputs<N> = {
    readonly [K in keyof N]: N[K] extends {
        readonly [detail]: {
            readonly instance: infer I;
        };
    } ? I : never;
};

export type RunOptions<N = {}> = {
    readonly signal?: AbortSignal | undefined;
    readonly scope?: unknown;
    readonly inputs?: RunInputs<N> | undefined;
};

export type SlotEntry<Id extends string, Rev extends number, S extends string, K extends Cardinality> = {
    readonly slotId: S;
    readonly capabilityId: Id;
    readonly compatibility: {
        readonly family: "exact";
        readonly familyVersion: 1;
        readonly token: `${Id}/r${Rev}`;
    };
    readonly cardinality: K;
    readonly [contractEntry]: true;
};

export type SuccessfulComposition = Extract<CompileCompositionResult, {
    readonly plan: CompositionPlan;
    readonly digest: PlanDigest;
}>;

export type UnresolvedBinding = {
    readonly consumerImplementationId: string;
    readonly slotId: string;
    readonly capabilityId: string;
    readonly cardinality: "required" | "optional" | "many";
    readonly groupPath: readonly string[];
    readonly candidates: readonly string[];
};

export type UsedKeysOf<M> = M extends {
    readonly [uses]: infer U;
} ? keyof U : M extends {
    readonly [groupUses]?: infer K;
} ? K : never;

export type UsedMap<C, K extends keyof C> = {
    readonly [P in K]: C[P];
};

export type ValidDeclaration<C, D extends ModuleDeclaration> = true extends IsUnion<D> | IsUnion<D["slots"]> | IsUnion<D["provides"]> | (D["slots"] extends infer Slots extends readonly unknown[] ? {
    [K in keyof Slots]: IsUnion<Slots[K]>;
}[number] : never) | (D["provides"] extends infer Provides extends readonly unknown[] ? {
    [K in keyof Provides]: IsUnion<Provides[K]>;
}[number] : never) ? never : number extends D["provides"]["length"] | D["slots"]["length"] ? never : [
    (D["provides"][number] | D["slots"][number] extends infer P ? P extends {
        readonly capabilityId: infer K extends string;
        readonly compatibility: infer T;
    } ? string extends K ? P : true extends IsUnion<K> ? P : K extends keyof C ? [
        T,
        (K extends keyof C ? C[K] extends {
            readonly compatibility: infer Compat;
        } ? Compat : never : never)
    ] extends [
        (K extends keyof C ? C[K] extends {
            readonly compatibility: infer Compat;
        } ? Compat : never : never),
        T
    ] ? never : P : P : P : never) | (D["slots"][number] extends infer S ? S extends {
        readonly slotId: infer K extends string;
        readonly cardinality: {
            readonly kind: infer Q;
        };
    } ? string extends K ? S : true extends IsUnion<K> | IsUnion<Q> ? S : never : S : never)
] extends [
    never
] ? unknown : never;

export declare function declareModule<const T extends DeclarationSpec>(spec: T & {
    readonly kind?: never;
    readonly schemaVersion?: never;
}): Declared<T>;

export declare function defineContract<V>(): <const Id extends string, const Rev extends number>(spec: {
    readonly id: Id;
    readonly revision: Rev;
}) => Contract<Id, V, Rev>;

export declare function implement<C>(): {
    <const D extends ModuleDeclaration, I>(declaration: D & ValidDeclaration<C, NoInfer<D>>, factory: ModuleFactory<C, NoInfer<D>, I>): ModuleEntry<C, D, I>;
    <const D extends ModuleDeclaration, I, X>(declaration: D & ValidDeclaration<C, NoInfer<D>>, factory: ModuleFactory<C, NoInfer<D>, I, X>, adapter: ContextAdapter<X>): ModuleEntry<C, D, I>;
};

export declare function input<C>(): <const D extends ModuleDeclaration & {
    readonly slots: readonly [
    ];
}>(declaration: D & ValidDeclaration<C, NoInfer<D>>) => InputEntry<C, D>;
